import os

class FileStorage:
    def __init__(self):
        self.files = []

    def add_file(self, filename):
        self.files.append(filename)

    def delete_files(self, limit):
        self.files = self.files[:limit]

    def get_cost(self, filename):
        # Assuming cost is based on file size
        return os.path.getsize(filename)

    def pay_to_keep_file(self, filename, payment):
        file_cost = self.get_cost(filename)
        if file_cost <= payment:
            self.add_file(filename)
            print(f"File {filename} has been saved. Cost: {file_cost}")
        else:
            print(f"File {filename} cannot be saved. Cost: {file_cost}. Payment: {payment}")

    def display_files(self):
        for file in self.files:
            print(file)

storage = FileStorage()

# Add files
for i in range(10000):
    storage.add_file(f"file_{i}")

# Delete files
storage.delete_files(10000)

# Pay to keep files
for i in range(10000, 20000):
    storage.pay_to_keep_file(f"file_{i}", 1000)

# Display remaining files
storage.display_files()
